(async function (data, args, reqOptions) {
  try {
    /* Access validation */
    if (!BeaconBar.user?.metaData?.menus?.includes("EIM/Languages.aspx")) {
      return {
        status: "NO_ACCESS",
        message: "You do not have access to Languages screen. Please contact HR Admin."
      };
    }

    /* Input validation */
    if (!args?.languageName || args.languageName.trim() === "") {
      return {
        status: "INVALID_ARGS",
        message: "Error: languageName is required"
      };
    }

    if (args.languageName.length > 120) {
      return {
        status: "INVALID_ARGS",
        message: "Error: languageName must be 120 characters or less"
      };
    }

    /* Initial page state */
    const details = await BeaconBar.executeFunction("getApiList")("Languages");

    const headers = new Headers();
    headers.append("Accept", "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8");
    headers.append("x-requested-with", "XMLHttpRequest");

    const updateUrl = await BeaconBar.executeFunction("updateUrlParams")("EIM/Languages.aspx");

    const url = updateUrl.updateUrl
      ? `${window.origin}/${reqOptions.sl}/${updateUrl.updateUrl}`
      : `${window.origin}/${reqOptions.sl}/EIM/Languages.aspx`;

    const parser = new DOMParser();

    /* Step 1: Click New to get the form with rating dropdown */
    const newFormData = new FormData();
    newFormData.append("scrollLeft", "0");
    newFormData.append("scrollTop", "0");
    newFormData.append("__EVENTTARGET", "");
    newFormData.append("__EVENTARGUMENT", "");
    newFormData.append("__VIEWSTATE", details.viewState);
    newFormData.append("__VIEWSTATEGENERATOR", details.viewStateGen);
    newFormData.append("__VIEWSTATEENCRYPTED", "");
    newFormData.append("__EVENTVALIDATION", details.eventValidation);
    newFormData.append("ctl00$hdnDateFormat", "dd/mm/yy");
    newFormData.append("ctl00$hdnQuickmenu", "1");
    newFormData.append("ctl00$body$ContentSearch$cboCriteria", "LANG_CODE");
    newFormData.append("ctl00$body$ContentSearch$txtContent", "");
    newFormData.append("ctl00$body$grdsummary$ctl00$ctl03$ctl01$GoToPageTextBox", "1");
    newFormData.append("ctl00_body_grdsummary_ctl00_ctl03_ctl01_GoToPageTextBox_ClientState", "");
    newFormData.append("ctl00$body$grdsummary$ctl00$ctl03$ctl01$ChangePageSizeTextBox", "10");
    newFormData.append("ctl00_body_grdsummary_ctl00_ctl03_ctl01_ChangePageSizeTextBox_ClientState", "");
    newFormData.append("ctl00_body_grdsummary_ClientState", "");
    newFormData.append("ctl00$body$butNew", "New");

    const newResponse = await fetch(url, {
      method: "POST",
      headers,
      body: newFormData
    });

    const newDoc = parser.parseFromString(await newResponse.text(), "text/html");

    /* Extract ViewState after clicking New */
    const viewState = newDoc.querySelector("#__VIEWSTATE")?.value || "";
    const eventValidation = newDoc.querySelector("#__EVENTVALIDATION")?.value || "";
    const viewStateGen = newDoc.querySelector("#__VIEWSTATEGENERATOR")?.value || "";

    /* Extract rating dropdown and find matching code (if rating is provided) */
    let ratingCodeToUse = "-1"; // Default to empty selection

    if (args.ratingCode || args.ratingName) {
      const ratingSelect = newDoc.querySelector("#ctl00_body_dprating");
      const options = ratingSelect?.querySelectorAll("option");

      // Determine rating code - prioritize direct code, then lookup name
      if (args.ratingCode !== undefined) {
        const inputRatingCode = args.ratingCode.trim();

        // If input is already a 6-digit code, use it directly
        if (/^\d{6}$/.test(inputRatingCode)) {
          ratingCodeToUse = inputRatingCode;
        } else {
          // Search for rating name (case-insensitive) in case user passed name to 'ratingCode' param
          for (const option of options) {
            const optionText = option.textContent.trim();
            const optionValue = option.value;

            if (optionValue !== "" && optionValue !== "-1" &&
                optionText.toLowerCase() === inputRatingCode.toLowerCase()) {
              ratingCodeToUse = optionValue;
              break;
            }
          }
        }
      } else if (args.ratingName !== undefined) {
        // Search for rating name (case-insensitive)
        const inputRatingName = args.ratingName.trim();

        for (const option of options) {
          const optionText = option.textContent.trim();
          const optionValue = option.value;

          if (optionValue !== "" && optionValue !== "-1" &&
              optionText.toLowerCase() === inputRatingName.toLowerCase()) {
            ratingCodeToUse = optionValue;
            break;
          }
        }
      }

      if (ratingCodeToUse === "-1") {
        // Collect available ratings for error message
        const availableRatings = Array.from(options)
          .filter(opt => opt.value !== "" && opt.value !== "-1")
          .map(opt => opt.textContent.trim());

        const searchTerm = args.ratingCode || args.ratingName;
        return {
          status: "INVALID_ARGS",
          message: `Rating "${searchTerm}" not found in the system`,
          suggestion: `Available ratings: ${availableRatings.join(", ")}`
        };
      }
    }

    /* Step 2: Save with the language name and rating code */
    const saveFormData = new FormData();
    saveFormData.append("scrollLeft", "0");
    saveFormData.append("scrollTop", "0");
    saveFormData.append("__EVENTTARGET", "");
    saveFormData.append("__EVENTARGUMENT", "");
    saveFormData.append("__VIEWSTATE", viewState);
    saveFormData.append("__VIEWSTATEGENERATOR", viewStateGen);
    saveFormData.append("__VIEWSTATEENCRYPTED", "");
    saveFormData.append("__EVENTVALIDATION", eventValidation);
    saveFormData.append("ctl00$hdnDateFormat", "dd/mm/yy");
    saveFormData.append("ctl00$hdnQuickmenu", "1");
    saveFormData.append("ctl00$body$txtName", args.languageName.trim());
    saveFormData.append("ctl00$body$dprating", ratingCodeToUse);
    saveFormData.append("ctl00$body$butSave", "Save");

    const saveResponse = await fetch(url, {
      method: "POST",
      headers,
      body: saveFormData
    });

    const saveHtml = await saveResponse.text();

    if (saveResponse.status === 200) {
      const saveDoc = parser.parseFromString(saveHtml, "text/html");
      const errorMsg = saveDoc.querySelector(".alert-danger, .error")?.textContent;

      if (errorMsg) {
        return {
          status: "ERROR",
          message: `Save failed: ${errorMsg.trim()}`
        };
      }

      // Extract the generated language code from the saved record
      const languageCode = saveDoc.querySelector("#ctl00_body_txtCode")?.value || "";

      return {
        status: "SUCCESS",
        message: "Successfully created Language!",
        languageName: args.languageName.trim(),
        languageCode: languageCode,
        rating: args.ratingCode || args.ratingName || "None",
        ratingCode: ratingCodeToUse !== "-1" ? ratingCodeToUse : null
      };
    }

    return {
      status: "ERROR",
      message: "Failed to create language. Please verify in the UI."
    };

  } catch (err) {
    return {
      status: "ERROR",
      message: err.message,
      error: err.toString()
    };
  }
})

